import { supabase, isSupabaseConfigured, requireSupabaseClient } from '../supabase/client';

/**
 * In-App Notifications Service (`src/services/notifications/notifications.service.js`).
 *
 * Security & Integrity:
 * - Queries only the authenticated user's own notifications (enforced by RLS `recipient_id = auth.uid()`).
 * - Never fabricates notifications.
 * - Security-sensitive notifications (like payment approval/rejection) are generated by
 *   the backend `review_manual_order` RPC with `dedupe_key` to prevent duplicates.
 */
export const notificationsService = {
  async listMyNotifications(limit = 20) {
    if (!isSupabaseConfigured || !supabase) {
      return [];
    }

    const {
      data: { session },
    } = await supabase.auth.getSession();

    if (!session?.user) {
      return [];
    }

    const { data, error } = await supabase
      .from('notifications')
      .select('*')
      .eq('recipient_id', session.user.id)
      .order('created_at', { ascending: false })
      .limit(limit);

    if (error) {
      throw error;
    }

    return data || [];
  },

  async markAsRead(notificationId) {
    const client = requireSupabaseClient();
    const { data, error } = await client
      .from('notifications')
      .update({ is_read: true, read_at: new Date().toISOString() })
      .eq('id', notificationId)
      .select()
      .single();

    if (error) {
      throw error;
    }
    return data;
  },

  async markAllAsRead() {
    const client = requireSupabaseClient();
    const {
      data: { session },
    } = await client.auth.getSession();

    if (!session?.user) return [];

    const { data, error } = await client
      .from('notifications')
      .update({ is_read: true, read_at: new Date().toISOString() })
      .eq('recipient_id', session.user.id)
      .eq('is_read', false)
      .select();

    if (error) {
      throw error;
    }
    return data || [];
  },
};

export default notificationsService;
